create or replace function public.ateek_reel_comment_v2(p_reel uuid,p_body text) returns uuid language plpgsql security definer set search_path=public as $$ declare v_uid uuid:=auth.uid();v_id uuid;v_owner uuid;v_permission text; begin if v_uid is null then raise exception 'AUTH_REQUIRED'; end if; select r.author_id,coalesce(p.comment_permission,'all') into v_owner,v_permission from public.reels r join public.ateek_profiles p on p.id=r.author_id where r.id=p_reel and r.status='active'; if v_owner is null then raise exception 'REEL_NOT_FOUND'; end if; if v_uid<>v_owner then if v_permission='none' then raise exception 'COMMENTS_DISABLED'; end if; if v_permission='followers' and not exists(select 1 from public.ateek_follows f where f.follower_id=v_uid and f.followed_id=v_owner) then raise exception 'FOLLOWERS_ONLY'; end if; end if; if length(trim(coalesce(p_body,'')))<1 or length(trim(p_body))>600 then raise exception 'INVALID_COMMENT'; end if; insert into public.reel_comments(reel_id,author_id,body) values(p_reel,v_uid,trim(p_body)) returning id into v_id; return v_id; end $$; revoke all on function public.ateek_reel_comment_v2(uuid,text) from public; grant execute on function public.ateek_reel_comment_v2(uuid,text) to authenticated;
